            recordBasketPurchase(asset, amount, pathDescription) {
                if (!this.basketHoldings[asset]) this.basketHoldings[asset] = 0;
                this.basketHoldings[asset] += amount;
                if (!this.acquisitionPaths[asset]) this.acquisitionPaths[asset] = [];
                this.acquisitionPaths[asset].push({ amount, path: pathDescription || 'unknown', time: new Date()
                        .toISOString() });
                this.save();
                UI.renderBasketTracker();
            },
            addBatchHistory(entry) {
                this.batchHistory.unshift(entry);
                if (this.batchHistory.length > 20) this.batchHistory.length = 20;
                this.save();
                UI.renderBatchHistory();
                UI.updateDashboard();
            },
            getAssetPrice(asset) {
                const stableTargets = ['USDT', 'USD', 'USDC', 'GUSD', 'BUSD'];
                for (const t of stableTargets) { const pair = this.allPairs.find(p => p.base === asset && p.target ===
                        t); if (pair) return pair.bidPrice || pair.price * 0.999; }
                const anyPair = this.allPairs.find(p => p.base === asset);
                if (anyPair) { const price = anyPair.bidPrice || anyPair.price * 0.999; if (!stableTargets.includes(
                        anyPair.target)) { const tp = this.getAssetPrice(anyPair.target); if (tp > 0) return price *
                        tp; } return price; }
                return 0;
            },
            computePurchasePower() {
                this.purchasePower = {}; if (this.bankroll <= 0) return;
                const prices = {};
                for (const pair of this.allPairs) { if (!pair.base || !pair.target) continue;
                    const ask = pair.askPrice || pair.price * 1.001; if (!prices[pair.base] || ask < prices[pair
                            .base]) prices[pair.base] = ask; }
                for (const [asset, price] of Object.entries(prices)) { if (price > 0) this.purchasePower[asset] = this
                        .bankroll / price; }
                for (const stable of ['USDT', 'USD', 'USDC', 'GUSD', 'BUSD']) { if (!this.purchasePower[stable]) this
                        .purchasePower[stable] = this.bankroll; }
            },
            getTargetAssets() { const raw = document.getElementById('targetAssetsInput')?.value.trim(); if (raw) return raw
                    .split(',').map(s => s.trim().toUpperCase()).filter(Boolean); return document.getElementById(
                        'basketInput').value.split(',').map(s => s.trim().toUpperCase()).filter(Boolean); },
            validateEdge(edge) { return edge && edge.rate > 0 && edge.rate < 1e6 && isFinite(edge.rate); },
            validateCycle(edges) { let p = 1; for (const e of edges) { if (!this.validateEdge(e)) return false;
                    p *= e.rate; } return p > 0.5 && p < 100; },
            getMaxCoinExchanges() { return Math.min(1 + Math.floor(this.level / 3), 8); },
            getCoinCooldown() { if (this.level < 5) return Infinity; return Math.max(60, 300 - (this.level - 5) *
