                    5) / 100; if (pct <= 0 || profit <= 0 || this.userCoins.length === 0) return; const amount = profit *
                    pct; if (amount <= 0 || this.bankroll < amount) return;
                this.bankroll -= amount;
                const totalWeight = this.userCoins.reduce((sum, c) => sum + (this.coinLevels[c.symbol] || 1), 0); let r =
                    Math.random() * totalWeight; for (const coin of this.userCoins) { const w = this.coinLevels[coin
