                    const old23 = localStorage.getItem('qfoam_v23');
                    if (old23) try { const d=JSON.parse(old23); this.bankroll=d.bankroll||10000; this.paperMatrix=d.paperMatrix||0; this.liveMatrix=d.liveMatrix||0; this.paperLevel=d.paperLevel||1; this.liveLevel=d.liveLevel||1; this.liveMode=d.liveMode||false; this.userCoins=d.userCoins||[]; this.selectedIntraExchanges=d.selectedIntraExchanges?new Set(d.selectedIntraExchanges):new Set(); this.forexRates=d.forexRates||{}; this.selectedFiats=d.selectedFiats?new Set(d.selectedFiats):new Set(); this.tradeLedger=d.tradeLedger?d.tradeLedger.slice(-15):[]; this.proxyMode=d.proxyMode||'direct'; this.customProxyUrl=d.customProxyUrl||''; this.execPath=d.execPath||'/execute'; this.basketHoldings=d.basketHoldings||{}; this.acquisitionPaths=d.acquisitionPaths||{}; } catch(e){}
