    let p2pPeer=null,p2pShareId=null;
    function startP2PShare(){if(p2pPeer){log('P2P share already active','warning');return;}p2pShareId='quantm-'+Math.random().toString(36).substr(2,8);p2pPeer=new Peer(p2pShareId,{host:'0.peerjs.com',port:443,secure:true,path:'/'});p2pPeer.on('open',(id)=>{document.getElementById('p2pShareStatus').textContent='Waiting for peer... (ID: '+id+')';log('🔗 P2P Share started, waiting for peer...','success');generateP2PQR(id);document.getElementById('stopP2PBtn').style.display='inline';});p2pPeer.on('connection',(conn)=>{conn.on('open',()=>{const htmlContent=document.documentElement.outerHTML;conn.send(htmlContent);document.getElementById('p2pShareStatus').textContent='Sent app to peer!';log('📤 App sent to peer via P2P!','success');});});p2pPeer.on('error',(err)=>{log('P2P Share error: '+err.message,'error');stopP2PShare();});}
    function stopP2PShare(){if(p2pPeer){p2pPeer.destroy();p2pPeer=null;}p2pShareId=null;document.getElementById('p2pShareStatus').textContent='Not started';document.getElementById('stopP2PBtn').style.display='none';const qrCanvas=document.getElementById('p2pQrCanvas');const ctx=qrCanvas.getContext('2d');ctx.clearRect(0,0,qrCanvas.width,qrCanvas.height);log('🔗 P2P Share stopped');}
    function generateP2PQR(peerId){const loaderHTML=`<!DOCTYPE html><html><head><meta charset="utf-8"><script src="https://unpkg.com/peerjs@1.5.1/dist/peerjs.min.js"></script></head><body style="background:#0a0a1a;color:#0f0;font-family:monospace;text-align:center;padding-top:40vh;">Loading QuanTM FOAM...</body><script>const targetId=window.location.hash.slice(1);const peer=new Peer();peer.on('open',(id)=>{const conn=peer.connect(targetId);conn.on('open',()=>{});conn.on('data',(data)=>{const blob=new Blob([data],{type:'text/html'});const url=URL.createObjectURL(blob);window.location=url;});conn.on('error',()=>{document.body.innerHTML='Connection failed. Try again.';});});peer.on('error',()=>{document.body.innerHTML='Peer error. Try again.';});<\/script></html>`;const fullUrl='data:text/html;charset=utf-8,'+encodeURIComponent(loaderHTML)+'#'+peerId;const qrCanvas=document.getElementById('p2pQrCanvas');QRCode.toCanvas(qrCanvas,fullUrl,{width:200,margin:1},(err)=>{if(err)log('P2P QR error: '+err,'error');});}

