        openTradeModal(oppStr){const opp=JSON.parse(decodeURIComponent(oppStr));const bet=Math.min(opp.maxTradeSize,parseFloat(document.getElementById('betInput').value)||1000);const sz=bet;let rt=sz;let ms=`Start: $${sz.toFixed(2)}<br>`;let valid=true;const dh=opp.edges.map((e,i)=>{const p=rt;rt*=e.rate;const suspicious=(e.rate>1e4||e.rate<1e-4||!isFinite(e.rate));if(suspicious)valid=false;ms+=`Hop ${i+1}: $${p.toFixed(2)} × ${e.rate.toFixed(6)} → $${rt.toFixed(2)}${suspicious?' ⚠️':''}<br>`;return`<div>${opp.path[i]} → ${opp.path[i+1]} | Liq: $${e.liquidity.toFixed(0)}${suspicious?' ⚠️ SUSPECT RATE':''}</div>`;}).join('');document.getElementById('tradeDetails').innerHTML=`<p>🔄 ${opp.path.join(' → ')}</p><p>💵 $${sz.toFixed(2)}</p>${dh}`;document.getElementById('compoundingMath').innerHTML=ms+`<strong>💰 Final: $${rt.toFixed(2)}</strong>`;const rateWarn=document.getElementById('rateWarning');if(!valid){rateWarn.innerHTML='<span style="color:#ffaa00;">⚠️ Anomalous rates detected.</span>';}else{rateWarn.innerHTML='';}const conflictWarn=document.getElementById('conflictWarning');const allPaths=[...State.highlightedPaths];const conflicts=allPaths.filter(p=>p!==opp.path&&p.some(n=>opp.path.includes(n)));if(conflicts.length>0){conflictWarn.innerHTML=`<span style="color:#ff4444;">⚠️ Shares nodes with ${conflicts.length} other payline(s).</span>`;}else{conflictWarn.innerHTML='';}document.getElementById('executeTradeBtn').onclick=async()=>{const now=Date.now();if(now-State.lastTradeExecTime<4000){log('⏳ Trade blocked','warning');return;}if(State.bankroll<=0){log('❌ Bankroll exhausted','error');return;}State.lastTradeExecTime=now;UI.logButton('EXECUTE TRADE');closeModal();await Engine.executeTrade(opp,sz,rt-sz);};document.getElementById('tradeModal').style.display='flex';},
